})

function setTouched(field: string) {
  touched.value[field] = true
}

function showError(field: string) {
  return (touched.value[field] || testResult.value !== null) ? errors[field] : undefined
}

const allFieldsFilled = computed(() => {
  const driver = values.driver

  switch (driver) {
    case 'mysql':
    case 'postgresql':
    case 'sqlserver':
    case 'oracle':
    case 'sqlite':
      return values.name && values.host && values.port && values.database_name && values.username && values.password
    case 'api':
      return values.name && values.api_base_url
    case 'file':
      if (values.file_source === 'url')
      return values.name && values.file_url && values.file_config?.format

      if (values.file_source === 'upload') {
        return values.name && values.file_upload && (
          (Array.isArray(values.file_upload) && values.file_upload.length > 0)
          || (!Array.isArray(values.file_upload) && values.file_upload)
        ) && values.file_config?.format
      }
      if (values.file_source === 'path')
      return values.name && values.file_path && values.file_config?.format

      return false
    default:
      return false
  }
})

const onSubmit = handleSubmit(async values => {
  try {
    // Prepare payload based on driver type
    const payload = {
      name: values.name,
      description: values.description,
      driver: values.driver,
      status: 'active',
      metadata: values.metadata,
    }

    // Add driver-specific fields
    switch (values.driver) {
      case 'mysql':
      case 'postgresql':
      case 'sqlserver':
      case 'oracle':
      case 'sqlite':
        Object.assign(payload, {
          host: values.host,
          port: values.port,
          database_name: values.database_name,
          username: values.username,
          password: values.password,
          options: values.options,
        })
        break
      case 'api':
        Object.assign(payload, {
          api_base_url: values.api_base_url,
          api_auth_type: values.api_auth_type,
          api_auth_config: values.api_auth_config,
        })
        break
      case 'file':
        Object.assign(payload, {
          file_source: values.file_source,
          file_url: values.file_url,
          file_path: values.file_path,
          file_upload: values.file_upload,
          file_config: values.file_config,
        })
        break
    }

    if (props.mode === 'create')
      await connectionStore.createItem(payload)
    else if (props.mode === 'edit')
      await connectionStore.updateItem(values.id, payload)

    close('submit')
  }
  catch (error) {
    console.error(error)
  }
})

async function onTestConnection() {
  // Mark all fields as touched to show errors
  Object.keys(values).forEach(setTouched)

  const { valid } = await validate()
  if (!valid) {
    console.log('errors', errors)
    testResult.value = null

    return
  }

  // Prepare test payload based on driver type
  const testPayload = {
    name: values.name,
    driver: values.driver,
  }

  switch (values.driver) {
    case 'mysql':
    case 'postgresql':
    case 'sqlserver':
    case 'oracle':
    case 'sqlite':
      Object.assign(testPayload, {
        host: values.host,
        port: values.port,
        database_name: values.database_name,
        username: values.username,
        password: values.password,
        options: values.options,
      })
