    case 'file':
      Object.assign(testPayload, {
        file_source: values.file_source,
        file_url: values.file_url,
        file_path: values.file_path,
        file_upload: values.file_upload,
        file_config: values.file_config,
      })
      break
  }

  testing.value = true

  const result = await connectionStore.testConnectionBeforeSave(testPayload)

  testResult.value = result
  testing.value = false
}

function close(result: 'close' | 'submit' | 'cancel' = 'close') {
  closeDialog(result)
}

