  }
  else {
    // Database connection
    setFieldValue('api_base_url', '')
    setFieldValue('api_auth_type', 'none')
    setFieldValue('api_auth_config', {})
    setFieldValue('file_path', '')
    setFieldValue('file_config', {
      format: 'csv',
      delimiter: ',',
      has_header: true,
      encoding: 'utf-8',
      date_format: 'Y-m-d H:i:s',
    })
  }

  // Clear test result when driver changes
  testResult.value = null
})

// Clear test result when form data changes
watch(values, () => {
  testResult.value = null
})

// Sincroniza el driver local con el del formulario
watch(() => values.driver, val => { driver.value = val })

const steps = [
  { title: 'Información básica', subtitle: 'Nombre, descripción y tipo' },
